sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  // Inicialização dos filtros
  $scope.anoSelecionado = "";
  $scope.mesSelecionado = "";
  $scope.bimestreSelecionadoRcl = "";

  $scope.anoChanged = function() {
    if (!$scope.anoSelecionado) {
      $scope.bimestreSelecionadoRcl = "";
      $scope.mesSelecionado = "";
      $rootScope.$broadcast('bimestreSelecionadoRcl', "");
      $rootScope.$broadcast('mesSelecionado', "");
      console.log("Ano limpo, mês e bimestre também limpos.");
    }
    $rootScope.$broadcast('anoSelecionado', $scope.anoSelecionado);
    console.log('Ano selecionado:', $scope.anoSelecionado);
  };

  $scope.mesChanged = function() {
    if ($scope.mesSelecionado) {
      $scope.bimestreSelecionadoRcl = "";
      $rootScope.$broadcast('bimestreSelecionadoRcl', "");
      console.log('Bimestre limpo porque mês foi selecionado');
    }
    $rootScope.$broadcast('mesSelecionado', $scope.mesSelecionado);
    console.log('Mês selecionado:', $scope.mesSelecionado);
  };

  $scope.bimestreChanged = function() {
    if ($scope.bimestreSelecionadoRcl) {
      $scope.mesSelecionado = "";
      $rootScope.$broadcast('mesSelecionado', "");
      console.log('Mês limpo porque bimestre foi selecionado');
    }
    $rootScope.$broadcast('bimestreSelecionadoRcl', $scope.bimestreSelecionadoRcl);
    console.log('Bimestre selecionado:', $scope.bimestreSelecionadoRcl);
  };

  $timeout(function() {
    $scope.anoChanged();
    $scope.mesChanged();
    $scope.bimestreChanged();
  });
}

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,400;600&display=swap');

.breadcrumb-bar {
    font-family: "Roboto Flex", sans-serif;
    display: flex;
    align-items: center;
    justify-content: space-between;
    background-color: #f8faff;
    border-radius: .6rem;
    padding: .8rem 1.5rem;
    color: #1e3a8a;
    font-size: 24px;
    box-shadow: 0 .1rem .2rem rgba(0, 0, 0, .05);
    flex-wrap: wrap; /* Permite quebrar linha em telas menores */
    gap: 10px;
}

.breadcrumb-links {
    display: flex;
    align-items: center;
    gap: 6px;
}

.breadcrumb-links a {
    color: #2563eb;
    text-decoration: none;
    font-weight: 500;
}

.breadcrumb-links a:hover {
    text-decoration: underline;
}

.breadcrumb-links span {
    color: #64748b;
}

/* --- Container para agrupar Ano e Mês --- */
.filters-wrapper {
    display: flex;
    align-items: center;
    gap: 20px; /* Espaço entre o filtro de Ano e Mês */
    flex-wrap: wrap;
}

/* --- Estilo Individual do Filtro --- */
.breadcrumb-filter {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
}

.breadcrumb-filter label {
    font-size: 10px;
    font-weight: 600;
    color: #9fa4c3;
    display: flex;
    align-items: center;
    margin-left: 26px;
    margin-bottom: -2px;
    text-transform: uppercase;
}

/* Select com ícone interno e seta customizada */
.filter-select {
    position: relative;
    display: flex;
    align-items: center;
    z-index: 99;
}

/* Ícone de filtro à esquerda */
.filter-select i {
    color: white;
    -webkit-text-stroke: 1px #4b5563;
    font-size: 16px;
    pointer-events: none;
    padding-right: 10px;
}

/* Seta para baixo */
.filter-select::after {
    content: "v";
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%) scaleY(0.9) scaleX(1.6);
    font-size: 14px;
    font-weight: 400;
    pointer-events: none;
    color: #334155;
}

/* Select estilizado */
.filter-select select {
    padding: 4px 26px 4px 8px;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    background-color: white;
    font-family: 'Roboto Flex', sans-serif;
    font-size: 13px;
    color: #334155;
    appearance: none;
    min-width: 110px; /* Um pouco mais largo para caber nomes de meses */
    cursor: pointer;
    height: 28px;
    display: flex;
    align-items: center;
}

.filter-select select:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 2px rgba(37,99,235,0.2);
}

/* Responsividade */
@media (min-width: 375px) and (max-width: 819px) {
    .breadcrumb-bar {
        font-size: 1.5rem;
        flex-direction: column;
        align-items: flex-start;
    }
    .filters-wrapper {
        width: 100%;
        justify-content: space-between;
        margin-top: 10px;
    }
}

@media (min-width: 820px) {
    .breadcrumb-bar {
        font-size: 2.5rem;
    }
}

sp_widget.script:
(function() {
  var anos = [];
  var meses = [];
  var bimestres = ['1', '2', '3', '4', '5', '6'];

  var anosUnicos = {};
  var mesesUnicos = {};

  // Coletando dados da tabela RCL
  var grRcl = new GlideRecord('x_sded9_portal_t_0_u_rcl_basica');
  grRcl.query();
  while (grRcl.next()) {
    var ano = grRcl.getValue('u_ano');
    if (ano && !anosUnicos[ano]) {
      anos.push(ano);
      anosUnicos[ano] = true;
    }
  }

  // Coletando dados da tabela RREO
  var grRreo = new GlideRecord('x_sded9_portal_t_0_u_rreo');
  grRreo.query();
  while (grRreo.next()) {
    // === SANEAR MÊS ===
    var mes = grRreo.getValue('u_mes');
    if (mes) {
      // Remove zeros à esquerda, converte para número, depois volta para string com 2 dígitos
      mes = ("0" + parseInt(mes)).slice(-2);

      if (!mesesUnicos[mes]) {
        meses.push(mes);
        mesesUnicos[mes] = true;
      }
    }

    var ano = grRreo.getValue('u_ano');
    if (ano && !anosUnicos[ano]) {
      anos.push(ano);
      anosUnicos[ano] = true;
    }
  }

  // Ordenar anos decrescente
  anos.sort(function(a, b) { return b - a; });

  // Ordenar meses crescente de 01 a 12
  meses.sort();

  data.anos = anos;
  data.meses = meses;
  data.bimestres = bimestres;
})();
